import{c as a,Q as t,j as s,m as o}from"./chunks/framework.rWdQudnF.js";const m=JSON.parse('{"title":"数据访问层设计","description":"","frontmatter":{"title":"数据访问层设计"},"headers":[],"relativePath":"架构师 在线刷题/51CT0题库 章节练习/层次式架构设计理论与实践（第二版）/数据访问层设计.md","filePath":"架构师 在线刷题/51CT0题库 章节练习/层次式架构设计理论与实践（第二版）/数据访问层设计.md","lastUpdated":null}'),i={name:"架构师 在线刷题/51CT0题库 章节练习/层次式架构设计理论与实践（第二版）/数据访问层设计.md"};function n(r,l,c,e,u,d){return t(),s("div",null,[...l[0]||(l[0]=[o('<h1 id="数据访问层设计" tabindex="-1">数据访问层设计 <a class="header-anchor" href="#数据访问层设计" aria-label="Permalink to &quot;数据访问层设计&quot;">​</a></h1><blockquote><p>共 14 题 · 题型：单选题 · 来源：51CTO题库</p></blockquote><h2 id="q1-持久层的主要功能是为-提供透明的数据访问、持久化、加载等能力。" tabindex="-1">Q1. 持久层的主要功能是为（ ）提供透明的数据访问、持久化、加载等能力。 <a class="header-anchor" href="#q1-持久层的主要功能是为-提供透明的数据访问、持久化、加载等能力。" aria-label="Permalink to &quot;Q1. 持久层的主要功能是为（ ）提供透明的数据访问、持久化、加载等能力。&quot;">​</a></h2><ul><li><strong>A.</strong> 视图</li><li><strong>B.</strong> 业务逻辑</li><li><strong>C.</strong> 控制层</li><li><strong>D.</strong> 表现层</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q2-数据访问层中-事务处理设计必须服从iso-iec所制定的-1-。在数据库连接管理中-为了提高数据库连接的有效复用-通常会采用-2-技术。" tabindex="-1">Q2. 数据访问层中，事务处理设计必须服从ISO/IEC所制定的 （1） 。在数据库连接管理中，为了提高数据库连接的有效复用，通常会采用 （2） 技术。 <a class="header-anchor" href="#q2-数据访问层中-事务处理设计必须服从iso-iec所制定的-1-。在数据库连接管理中-为了提高数据库连接的有效复用-通常会采用-2-技术。" aria-label="Permalink to &quot;Q2. 数据访问层中，事务处理设计必须服从ISO/IEC所制定的 （1） 。在数据库连接管理中，为了提高数据库连接的有效复用，通常会采用 （2） 技术。&quot;">​</a></h2><ul><li><strong>A.</strong> ACID原则</li><li><strong>B.</strong> MVC原则</li><li><strong>C.</strong> MVP原则</li><li><strong>D.</strong> ORM原则</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><h2 id="q3-数据访问层中-事务处理设计必须服从iso-iec所制定的-1-。在数据库连接管理中-为了提高数据库连接的有效复用-通常会采用-2-技术。" tabindex="-1">Q3. 数据访问层中，事务处理设计必须服从ISO/IEC所制定的 （1） 。在数据库连接管理中，为了提高数据库连接的有效复用，通常会采用 （2） 技术。 <a class="header-anchor" href="#q3-数据访问层中-事务处理设计必须服从iso-iec所制定的-1-。在数据库连接管理中-为了提高数据库连接的有效复用-通常会采用-2-技术。" aria-label="Permalink to &quot;Q3. 数据访问层中，事务处理设计必须服从ISO/IEC所制定的 （1） 。在数据库连接管理中，为了提高数据库连接的有效复用，通常会采用 （2） 技术。&quot;">​</a></h2><ul><li><strong>A.</strong> 在线访问</li><li><strong>B.</strong> 连接池</li><li><strong>C.</strong> DTO</li><li><strong>D.</strong> ORM映射</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q4-数据库连接池的主要目的是-1-数据访问模式中的-离线数据模式-特点是-2-。" tabindex="-1">Q4. 数据库连接池的主要目的是 （1） ；数据访问模式中的“离线数据模式”特点是 （2） 。 <a class="header-anchor" href="#q4-数据库连接池的主要目的是-1-数据访问模式中的-离线数据模式-特点是-2-。" aria-label="Permalink to &quot;Q4. 数据库连接池的主要目的是 （1） ；数据访问模式中的“离线数据模式”特点是 （2） 。&quot;">​</a></h2><ul><li><strong>A.</strong> 提高数据查询速度</li><li><strong>B.</strong> 复用数据库连接</li><li><strong>C.</strong> 加密传输数据</li><li><strong>D.</strong> 生成SQL语句</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q5-数据库连接池的主要目的是-1-数据访问模式中的-离线数据模式-特点是-2-。" tabindex="-1">Q5. 数据库连接池的主要目的是 （1） ；数据访问模式中的“离线数据模式”特点是 （2） 。 <a class="header-anchor" href="#q5-数据库连接池的主要目的是-1-数据访问模式中的-离线数据模式-特点是-2-。" aria-label="Permalink to &quot;Q5. 数据库连接池的主要目的是 （1） ；数据访问模式中的“离线数据模式”特点是 （2） 。&quot;">​</a></h2><ul><li><strong>A.</strong> 数据以预定义结构形式缓存</li><li><strong>B.</strong> 实时与数据库交互</li><li><strong>C.</strong> 依赖网络传输带宽</li><li><strong>D.</strong> 每次数据操作分配一个连接</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><h2 id="q6-在事务处理设计中-acid原则中的-i-代表什么-。" tabindex="-1">Q6. 在事务处理设计中，ACID原则中的&quot;I&quot;代表什么（ ）。 <a class="header-anchor" href="#q6-在事务处理设计中-acid原则中的-i-代表什么-。" aria-label="Permalink to &quot;Q6. 在事务处理设计中，ACID原则中的&quot;I&quot;代表什么（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 原子性（Atomicity）</li><li><strong>B.</strong> 一致性（Consistency）</li><li><strong>C.</strong> 隔离性（Isolation）</li><li><strong>D.</strong> 持久性（Durability）</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q7-关于orm-object-relation-mapping-的主要作用-以下描述最准确的是-。" tabindex="-1">Q7. 关于ORM（Object-Relation Mapping）的主要作用，以下描述最准确的是（ ）。 <a class="header-anchor" href="#q7-关于orm-object-relation-mapping-的主要作用-以下描述最准确的是-。" aria-label="Permalink to &quot;Q7. 关于ORM（Object-Relation Mapping）的主要作用，以下描述最准确的是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 直接操作SQL语句</li><li><strong>B.</strong> 在关系型数据库和对象之间建立映射</li><li><strong>C.</strong> 优化数据库性能</li><li><strong>D.</strong> 管理数据库连接池</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q8-在数据访问层应用工厂模式的主要目的是什么-。" tabindex="-1">Q8. 在数据访问层应用工厂模式的主要目的是什么（ ）。 <a class="header-anchor" href="#q8-在数据访问层应用工厂模式的主要目的是什么-。" aria-label="Permalink to &quot;Q8. 在数据访问层应用工厂模式的主要目的是什么（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 提高数据库查询效率</li><li><strong>B.</strong> 实现数据库连接池</li><li><strong>C.</strong> 使对象的实例化延迟到子类</li><li><strong>D.</strong> 简化SQL语句的编写</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q9-对象-关系映射-o-r-mapping-的主要作用是什么-。" tabindex="-1">Q9. 对象/关系映射（O/R Mapping）的主要作用是什么（ ）。 <a class="header-anchor" href="#q9-对象-关系映射-o-r-mapping-的主要作用是什么-。" aria-label="Permalink to &quot;Q9. 对象/关系映射（O/R Mapping）的主要作用是什么（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 优化SQL查询性能</li><li><strong>B.</strong> 实现数据库分片</li><li><strong>C.</strong> 转换应用程序对象和关系数据库记录</li><li><strong>D.</strong> 管理数据库连接池</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q10-在dao-数据访问对象-模式中-以下哪项不是其主要优点-。" tabindex="-1">Q10. 在DAO（数据访问对象）模式中，以下哪项不是其主要优点（ ）。 <a class="header-anchor" href="#q10-在dao-数据访问对象-模式中-以下哪项不是其主要优点-。" aria-label="Permalink to &quot;Q10. 在DAO（数据访问对象）模式中，以下哪项不是其主要优点（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 减少代码量</li><li><strong>B.</strong> 增强程序的可移植性</li><li><strong>C.</strong> 提高代码的可读性</li><li><strong>D.</strong> 提高数据库查询性能</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><h2 id="q11-关于在线访问模式的特点-以下说法正确的是-。" tabindex="-1">Q11. 关于在线访问模式的特点，以下说法正确的是（ ）。 <a class="header-anchor" href="#q11-关于在线访问模式的特点-以下说法正确的是-。" aria-label="Permalink to &quot;Q11. 关于在线访问模式的特点，以下说法正确的是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 业务对象和数据访问代码完全解耦</li><li><strong>B.</strong> 无法处理复杂的Select语句</li><li><strong>C.</strong> 性能比直接的SQL要优越一些</li><li><strong>D.</strong> 不需要开发人员了解SQL语句</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q12-下列数据访问模式中-操作会持续占用一个活动的数据库连接-并与数据源实时交互的是-1-dao-data-access-object-设计模式实现中-组成部分通常不包括-2-。" tabindex="-1">Q12. 下列数据访问模式中，操作会持续占用一个活动的数据库连接，并与数据源实时交互的是 （1） ；DAO（Data Access Object）设计模式实现中，组成部分通常不包括 （2） 。 <a class="header-anchor" href="#q12-下列数据访问模式中-操作会持续占用一个活动的数据库连接-并与数据源实时交互的是-1-dao-data-access-object-设计模式实现中-组成部分通常不包括-2-。" aria-label="Permalink to &quot;Q12. 下列数据访问模式中，操作会持续占用一个活动的数据库连接，并与数据源实时交互的是 （1） ；DAO（Data Access Object）设计模式实现中，组成部分通常不包括 （2） 。&quot;">​</a></h2><ul><li><strong>A.</strong> 在线访问（Online Access）</li><li><strong>B.</strong> 数据访问对象（DAO）</li><li><strong>C.</strong> 数据传输对象（DTO）</li><li><strong>D.</strong> 离线数据模式（Offline Data Pattern）</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><h2 id="q13-下列数据访问模式中-操作会持续占用一个活动的数据库连接-并与数据源实时交互的是-1-dao-data-access-object-设计模式实现中-组成部分通常不包括-2-。" tabindex="-1">Q13. 下列数据访问模式中，操作会持续占用一个活动的数据库连接，并与数据源实时交互的是 （1） ；DAO（Data Access Object）设计模式实现中，组成部分通常不包括 （2） 。 <a class="header-anchor" href="#q13-下列数据访问模式中-操作会持续占用一个活动的数据库连接-并与数据源实时交互的是-1-dao-data-access-object-设计模式实现中-组成部分通常不包括-2-。" aria-label="Permalink to &quot;Q13. 下列数据访问模式中，操作会持续占用一个活动的数据库连接，并与数据源实时交互的是 （1） ；DAO（Data Access Object）设计模式实现中，组成部分通常不包括 （2） 。&quot;">​</a></h2><ul><li><strong>A.</strong> DAO工厂类（DAO Factory）</li><li><strong>B.</strong> DAO接口（DAO Interface）</li><li><strong>C.</strong> 实现了DAO接口的具体类（Concrete DAO）</li><li><strong>D.</strong> 数据库连接池（Database Connection Pool）</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><h2 id="q14-【问题1】-8分-hibernate与ibatis均提供orm技术-请用300以内文字说明什么是orm技术-以及有什么优点" tabindex="-1">Q14. 【问题1】（8分）Hibernate与iBatis均提供ORM技术，请用300以内文字说明什么是ORM技术，以及有什么优点？ <a class="header-anchor" href="#q14-【问题1】-8分-hibernate与ibatis均提供orm技术-请用300以内文字说明什么是orm技术-以及有什么优点" aria-label="Permalink to &quot;Q14. 【问题1】（8分）Hibernate与iBatis均提供ORM技术，请用300以内文字说明什么是ORM技术，以及有什么优点？&quot;">​</a></h2><details class="callout callout-info"><summary class="callout-title"><span class="callout-icon">ℹ️</span>材料</summary><div class="callout-body"><p>试题五阅读以下关于Web系统架构的设计的叙述，回答下列问题。【说明】某信息技术公司计划开发一套在线投票系统，用于为市场调研、信息调查和销售反馈等业务提供服务。该系统计划通过大量宣传和奖品鼓励的方式快速积累用户，当用户规模扩大到一定程度时，开始联系相关企业提供信息服务，并按照信息服务种类和用户投票数量收取费用。为了降低开发成本和提高开发效率，项目组经过讨论后决定采用轻量级Java EE开发框架设计系统应用架构。在应用架构设计中，除了满足系统主要功能需求，还需要考虑的因素包括：1.项目开发采用MySQL，数据库存储数据，但将来可能移植到其他数据库平台；2.系统开发过程中尽可能降低或者消除SQL语句开发的工作量；3.投票系统中数据之间的关系复杂，需要支持数据对象的聚合和继承等关系。项目组基于MVC模式设计出了投票系统的架构，包括表示层、业务逻辑层、数据持久层和数据层。在具体讨论数据持久层采用哪种技术方案时，老王建议采用成熟的Hibernate框架，小李则认为iBatis更加灵活，更适合作为投票系统数据持久层开发技术。</p></div></details><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>ORM的全称是：Object Relational Mapping（对象关系映射）。简单的说，ORM是通过使用描述对象和数据之间映射的元数据，将程序中的对象自动持久化到关系数据库中。ORM的优点：（1）提高开发效率，降低开发成本；（2）使开发更加对象化；（3）可移植；（4）可以很方便地引入数据缓存之类的附加功能。</p></div></details>',44)])])}const p=a(i,[["render",n]]);export{m as __pageData,p as default};
